const PRICE_THRESHOLD = 0.15;

function parsePrice(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(String(value).replace(/,/g, '').trim());
  return Number.isFinite(n) ? n : null;
}

function validatePrice(price, allowZero = false) {
  if (price === null) return { ok: false, reason: 'missing_price' };
  if (price < 0) return { ok: false, reason: 'negative_price' };
  if (price === 0 && !allowZero) return { ok: false, reason: 'zero_price_not_allowed' };
  return { ok: true };
}

function shouldImportImage(imageUrl, existingImages) {
  if (!imageUrl || !/^https?:\/\//i.test(imageUrl)) return false;
  if (!existingImages?.length) return true;
  const norm = imageUrl.split('?')[0];
  return !existingImages.some((img) => img.src && img.src.split('?')[0] === norm);
}

const creds = await this.getCredentials('wooCommerceApi');
const baseUrl = (creds.url || 'https://cttel.ir').replace(/\/$/, '');
const auth = { username: creds.consumerKey, password: creds.consumerSecret };

const dryRun = $input.first().json.dry_run === true || $input.first().json.dry_run === 'true';
const products = $input.first().json.products || [];

const summary = {
  dry_run: dryRun,
  created: [],
  updated: [],
  skipped: [],
  errors: [],
  price_changes: [],
  stock_changes: [],
  price_approvals: [],
  unknown_categories: [],
};

const staticData = $getWorkflowStaticData('global');
if (!staticData.logs) staticData.logs = [];
const ts = new Date().toISOString();

const categoryCache = {};

async function wcRequest(method, path, qs = {}, body = undefined) {
  return await this.helpers.httpRequest({
    method,
    url: `${baseUrl}/wp-json/wc/v3${path}`,
    qs,
    body,
    json: true,
    auth,
  });
}

async function findBySku(sku) {
  const list = await wcRequest.call(this, 'GET', '/products', { sku, per_page: 1 });
  return Array.isArray(list) && list.length ? list[0] : null;
}

async function findCategory(slug) {
  if (!slug) return null;
  if (categoryCache[slug] !== undefined) return categoryCache[slug];
  const list = await wcRequest.call(this, 'GET', '/products/categories', { slug, per_page: 1 });
  const cat = Array.isArray(list) && list.length ? list[0] : null;
  categoryCache[slug] = cat;
  return cat;
}

function logEntry(entry) {
  staticData.logs.push(entry);
  if (staticData.logs.length > 500) staticData.logs = staticData.logs.slice(-500);
}

for (const input of products) {
  const sku = String(input.sku || '').trim();
  if (!sku) {
    summary.errors.push({ sku: '', error: 'missing_sku' });
    continue;
  }

  let existing = null;
  try {
    existing = await findBySku.call(this, sku);
  } catch (e) {
    summary.errors.push({ sku, error: 'wc_lookup_failed', detail: String(e.message || e) });
    logEntry({ timestamp: ts, sku, action: 'error', status: 'error', error: 'wc_lookup_failed' });
    continue;
  }

  const isUpdate = Boolean(existing?.id);
  const oldRegular = parsePrice(existing?.regular_price);
  const oldSale = parsePrice(existing?.sale_price);
  const effectiveOld = oldSale ?? oldRegular;
  const oldStock = existing?.stock_quantity != null ? Number(existing.stock_quantity) : null;

  const payload = {
    sku,
    name: input.name || existing?.name || sku,
    status: input.status || existing?.status || 'publish',
    manage_stock: input.manage_stock !== false,
    meta_data: [{ key: '_cttel_installment_available', value: input.installment_available ? 'yes' : 'no' }],
  };

  if (input.short_description) payload.short_description = input.short_description;
  if (input.description) payload.description = input.description;

  if (input.regular_price !== undefined && input.regular_price !== null && String(input.regular_price).trim() !== '') {
    const np = parsePrice(input.regular_price);
    const v = validatePrice(np);
    if (!v.ok) {
      summary.skipped.push({ sku, reason: `regular_price:${v.reason}` });
      logEntry({ timestamp: ts, sku, action: 'skip', status: 'skipped', error: v.reason });
      continue;
    }
    payload.regular_price = String(np);
  } else if (!isUpdate) {
    summary.skipped.push({ sku, reason: 'regular_price_required_for_create' });
    continue;
  }

  if (input.sale_price !== undefined && input.sale_price !== null && String(input.sale_price).trim() !== '') {
    const sp = parsePrice(input.sale_price);
    const v = validatePrice(sp);
    if (!v.ok) {
      summary.skipped.push({ sku, reason: `sale_price:${v.reason}` });
      continue;
    }
    payload.sale_price = String(sp);
  }

  let stockSkipped = false;
  if (input.stock_quantity === null || input.stock_quantity === undefined || input.stock_quantity === '') {
    stockSkipped = true;
  } else {
    const qty = Number(input.stock_quantity);
    if (!Number.isFinite(qty) || qty < 0) {
      stockSkipped = true;
      summary.skipped.push({ sku, reason: 'stock_malformed' });
      logEntry({ timestamp: ts, sku, action: 'skip', status: 'skipped', error: 'stock_malformed' });
      continue;
    }
    payload.stock_quantity = qty;
    payload.stock_status = qty === 0 ? 'outofstock' : 'instock';
  }

  if (input.featured === true) payload.featured = true;
  else if (input.featured === false && isUpdate) payload.featured = false;

  const categorySlug = String(input.category || '').trim();
  if (categorySlug) {
    try {
      const cat = await findCategory.call(this, categorySlug);
      if (!cat) {
        summary.unknown_categories.push({ sku, category: categorySlug });
      } else {
        payload.categories = [{ id: cat.id }];
      }
    } catch (e) {
      summary.errors.push({ sku, error: 'category_lookup_failed' });
    }
  }

  const imageUrl = String(input.image_url || '').trim();
  if (shouldImportImage(imageUrl, existing?.images)) {
    payload.images = [{ src: imageUrl }];
  }

  const effectiveNew = parsePrice(payload.sale_price) ?? parsePrice(payload.regular_price);
  let pct = null;
  if (effectiveOld != null && effectiveNew != null && effectiveOld > 0) {
    pct = Math.abs(effectiveNew - effectiveOld) / effectiveOld;
  }

  if (pct != null && pct > PRICE_THRESHOLD) {
    summary.price_approvals.push({
      sku,
      name: payload.name,
      old_price: effectiveOld,
      new_price: effectiveNew,
      percentage_change: Math.round(pct * 10000) / 100,
    });
    logEntry({ timestamp: ts, sku, action: 'price_approval', old_price: effectiveOld, new_price: effectiveNew, status: 'pending' });
    continue;
  }

  if (effectiveOld != null && effectiveNew != null && effectiveOld !== effectiveNew) {
    summary.price_changes.push({ sku, name: payload.name, old_price: effectiveOld, new_price: effectiveNew });
  }
  if (!stockSkipped && oldStock !== null && payload.stock_quantity !== oldStock) {
    summary.stock_changes.push({ sku, name: payload.name, old_stock: oldStock, new_stock: payload.stock_quantity });
  }

  const action = isUpdate ? 'update' : 'create';

  if (dryRun) {
    summary[action === 'create' ? 'created' : 'updated'].push({ sku, name: payload.name, dry_run: true, payload_preview: payload });
    logEntry({ timestamp: ts, sku, action: `dry_run_${action}`, old_price: effectiveOld, new_price: effectiveNew, old_stock: oldStock, new_stock: stockSkipped ? null : payload.stock_quantity, status: 'dry_run' });
    continue;
  }

  try {
    if (isUpdate) {
      await wcRequest.call(this, 'PUT', `/products/${existing.id}`, {}, payload);
      summary.updated.push({ sku, name: payload.name, id: existing.id });
    } else {
      const created = await wcRequest.call(this, 'POST', '/products', {}, payload);
      summary.created.push({ sku, name: payload.name, id: created.id });
    }
    logEntry({ timestamp: ts, sku, action, old_price: effectiveOld, new_price: effectiveNew, old_stock: oldStock, new_stock: stockSkipped ? null : payload.stock_quantity, status: 'ok' });
  } catch (e) {
    summary.errors.push({ sku, error: 'wc_write_failed', detail: String(e.message || e) });
    logEntry({ timestamp: ts, sku, action, status: 'error', error: String(e.message || e) });
  }
}

return [{ json: summary }];

const s = $input.first().json;
const lines = [
  'CTTEL Product Sync',
  '',
  `DRY_RUN: ${s.dry_run ? 'true' : 'false'}`,
  '',
  `Created: ${s.created?.length ?? 0}`,
  `Updated: ${s.updated?.length ?? 0}`,
  `Skipped: ${s.skipped?.length ?? 0}`,
  `Errors: ${s.errors?.length ?? 0}`,
  '',
  'Price changes:',
];
for (const p of (s.price_changes || []).slice(0, 15)) {
  lines.push(`• ${p.sku} ${p.name}: ${p.old_price} → ${p.new_price}`);
}
lines.push('', 'Stock changes:');
for (const p of (s.stock_changes || []).slice(0, 15)) {
  lines.push(`• ${p.sku} ${p.name}: ${p.old_stock} → ${p.new_stock}`);
}
if ((s.errors || []).length) {
  lines.push('', 'Errors:');
  for (const e of s.errors.slice(0, 10)) {
    lines.push(`• ${e.sku || '-'} ${e.error}`);
  }
}
if ((s.unknown_categories || []).length) {
  lines.push('', 'UNKNOWN CATEGORY:');
  for (const u of s.unknown_categories) {
    lines.push(`• ${u.sku} → ${u.category}`);
  }
}
return [{ json: { ...s, telegram_summary: lines.join('\n') } }];

const s = $input.first().json;
const approvals = s.price_approvals || [];
if (!approvals.length) {
  return [];
}
const lines = [
  '⚠️ CTTEL Price Approval Required',
  'Change > 15% — NOT applied automatically.',
  '',
];
for (const a of approvals) {
  lines.push(`${a.sku} — ${a.name}`);
  lines.push(`  ${a.old_price} → ${a.new_price} (${a.percentage_change}%)`);
  lines.push('');
}
return [{ json: { telegram_text: lines.join('\n') } }];
